{
  "manifest_version": 3,
  "name": "Temu 店铺监测",
  "version": "0.1.0",
  "description": "监测 Temu 后台在售数量下降 / 商品流量异常，异常时发飞书告警。数据仅在本机处理，不上传任何服务器。",
  "permissions": ["storage", "alarms", "tabs", "idle"],
  "host_permissions": [
    "https://agentseller.temu.com/*",
    "https://www.temu.com/*",
    "https://open.feishu.cn/*",
    "https://open.larksuite.com/*"
  ],
  "background": { "service_worker": "background.js" },
  "action": { "default_popup": "popup.html", "default_title": "Temu 店铺监测" },
  "options_page": "options.html",
  "content_scripts": [
    {
      "matches": ["https://agentseller.temu.com/*"],
      "js": ["logger.js", "content.js"],
      "run_at": "document_start"
    },
    {
      "matches": ["https://www.temu.com/*"],
      "js": ["logger.js", "content-front.js"],
      "run_at": "document_idle"
    }
  ],
  "web_accessible_resources": [
    { "resources": ["inject.js"], "matches": ["https://agentseller.temu.com/*"] }
  ]
}

content.content:
1	// 隔离世界：① 注入 inject.js；② 转发接口响应(带当前店名)；③ 读流量待关注 chip；
2	// ④ 接收后台指令自动切店(轮巡用)。
3	(function () {
4	  var LOG = TemuLogger.createLogger('content');
5	  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
6	  LOG.info('content.js loaded -- v12');
7	
8	  // 页面操作互斥锁：scanWatchList/scanOnSaleList/switchTo 都会改动「快速筛选/tab/切店」状态，
9	  // 绝不能并发——否则「商品流量待关注」筛选一打开，并发的在售扫描就只扫到筛选后的几条，
10	  // 误判成「下架 N 个」（这是历史假告警「在售 13→3」的根因）。所有改动型指令排队串行执行。
11	  let opChain = Promise.resolve();
12	  function withLock(fn) {
13	    const run = opChain.then(fn, fn); // 无论上一个成功/失败都接着跑（fn 不依赖上个结果）
14	    opChain = run.then(() => {}, (e) => { LOG.warn('Locked operation failed: ' + (e && e.message || e)); }); // 吞掉结果/异常，保持链条连续
15	    return run; // 调用方拿到 fn 的真实结果/异常
16	  }
17	
18	  // 注入 MAIN world hook
19	  try {
20	    const s = document.createElement('script');
21	    s.src = chrome.runtime.getURL('inject.js');
22	    s.onload = () => s.remove();
23	    (document.head || document.documentElement).appendChild(s);
24	    LOG.info('inject.js injected into MAIN world');
25	  } catch (e) { LOG.warn('inject.js injection failed: ' + (e && e.message || e)); }
26	
27	  // ---------- 读当前店铺名（右上角英文店名） ----------
28	  // 假店名黑名单：商品颜色/规格/尺码常被误读成「店名」写进 storage
29	  // （历史假店：Beige/Black/Charcoal/Grey/Rustic Brown/White Grey/Black Grey…）
30	  const FAKE_STORE_WORDS = /^(black|white|grey|gray|beige|brown|charcoal|red|blue|green|pink|purple|yellow|orange|gold|silver|ivory|cream|navy|olive|tan|khaki|maroon|coral|mint|teal|cyan|magenta|wine|rose|nude|camel|sand|stone|rustic|dark|light|natural|clear|multi|assorted|random|one size|os|xs|s|m|l|xl|xxl|xxxl|sku|skc|spu|usd|cny|eur|gbp|new|beta|seller|central|best|seller|english|chinese|all|more|less|edit|save|submit|cancel|close|next|prev|back|home|cart|account|login|sign|menu|search|help|support|local|warehouse|free|shipping|sale|off|pack|size|color|colour|style|qty|quantity|option|select)$/i;
31	  function isFakeStoreName(t) {
32	    if (!t) return true;
33	    const s = String(t).trim();
34	    if (s.length < 2 || s.length > 30) return true;
35	    // 纯大写+数字货号
36	    if (/^[A-Z0-9]+$/.test(s)) return true;
37	    // UI 固定词
38	    if (/^(Seller Central|Beta|NEW|SKC|SKU|USD|Best Seller)$/i.test(s)) return true;
39	    // 整句是颜色/规格词（含多词如 "Rustic Brown" / "Black Grey" / "Ivory White"）
40	    const words = s.split(/\s+/);
41	    if (words.every((w) => FAKE_STORE_WORDS.test(w))) return true;
42	    // 单色词（"Black"）
43	    if (words.length === 1 && FAKE_STORE_WORDS.test(words[0])) return true;
44	    return false;
45	  }
46	  function findStoreNameEl() {
47	    const W = window.innerWidth;
48	    let best = null;
49	    for (const el of document.querySelectorAll('span,a,div,button,p')) {
50	      const t = (el.textContent || '').trim();
51	      if (!/^[A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,3}$/.test(t)) continue;
52	      if (isFakeStoreName(t)) continue;
53	      if (el.children.length > 2) continue;
54	      const r = el.getBoundingClientRect();
55	      if (r.width === 0 || r.top < 0 || r.top > 90) continue;
56	      if (r.left < W * 0.5) continue;
57	      if (!best || r.left > best.left) best = { el, left: r.left };
58	    }
59	    return best ? best.el : null;
60	  }
61	  function readStoreName() {
62	    const el = findStoreNameEl();
63	    if (!el) return null;
64	    const t = (el.textContent || '').trim();
65	    return isFakeStoreName(t) ? null : t;
66	  }
67	
68	  // ---------- 转发接口响应 ----------
69	  window.addEventListener('message', (e) => {
70	    if (e.source !== window) return;
71	    const d = e.data;
72	    if (!d || d.__temuMon !== true) return;
73	    try { chrome.runtime.sendMessage({ type: 'capture', kind: d.kind, url: d.url, body: d.body, store: readStoreName() }); } catch (err) {}
74	  });
75	
76	  // ---------- 读流量异常 ----------
77	  // ①「商品流量待关注」是常驻的快速筛选 chip，实测 DOM（勿凭空改）：
78	  //     <div class="use-quick-field_tsx_card__HASH"><span>商品流量待关注</span>
79	  //       <span class="use-quick-field_tsx_countDistance__HASH">4</span></div>
80	  //   计数在独立的 countDistance span 里（chip 常驻，N=0 也在，只有 N 变大才是真异常）。
81	  // ②「商品流量近期有下降」不是 chip，是逐行红色徽标（见 countDeclineBadges）。
82	  // 关键坑：行内徽标「商品流量待关注 ›」嵌在价格 TD 里 → 价格单元格文本也含该标签。
83	  //   旧的"全页捞文本+最短优先"靠排序巧合才没读到价格数字；这里改为直接锚定 chip 容器。
84	  function readChipCount(all, label) {
85	    const re = new RegExp(label);
86	    // 精确路径：定位快速筛选 chip 容器（class 前缀 use-quick-field_tsx_card__ 稳定，
87	    // hash 后缀随构建变，用 *= 匹配前缀；card__ 带双下划线以免误匹配 cardBlock__）。
88	    for (const card of document.querySelectorAll('[class*="use-quick-field_tsx_card__"]')) {
89	      if (!re.test(card.textContent || '')) continue;
90	      const cnt = card.querySelector('[class*="countDistance"]');
91	      if (cnt && /\d/.test(cnt.textContent || '')) {
92	        return Number((cnt.textContent || '').replace(/[^\d]/g, ''));
93	      }
94	      const m = (card.textContent || '').match(new RegExp(label + '[^\\d]{0,3}([\\d,]+)'));
95	      if (m) return Number(m[1].replace(/,/g, ''));
96	    }
97	    // 兜底：chip class 若被改名，退回旧的全页文本匹配（最短优先 + 就近数字）
98	    const labels = all
99	      .filter((e) => re.test(e.textContent || '') && (e.textContent || '').trim().length < 24)
100	      .sort((a, b) => (a.textContent || '').length - (b.textContent || '').length);
101	    for (const el of labels) {
102	      for (const cand of [el, el.parentElement, el.parentElement && el.parentElement.parentElement]) {
103	        if (!cand) continue;
104	        const m = (cand.textContent || '').match(new RegExp(label + '[^\\d]{0,3}([\\d,]+)'));
105	        if (m) return Number(m[1].replace(/,/g, ''));
106	      }
107	      let sib = el.nextElementSibling;
108	      for (let i = 0; i < 3 && sib; i++, sib = sib.nextElementSibling) {
109	        const st = (sib.textContent || '').trim();
110	        if (/^[\d,]+$/.test(st)) return Number(st.replace(/,/g, ''));
111	      }
112	    }
113	    return null; // 读不到 → 未知（不当作 0，也不当作"有"）
114	  }
115	  // 「商品流量近期有下降」不是带计数的筛选 chip，而是逐行的红色徽标（列「商品优化事项」下）。
116	  // 因此按"当前页可见的行内徽标个数"来统计。注意：只覆盖当前页（默认 20 条/页），
117	  // 下降商品若在其它页则数不到——被动读数的固有限制，要精确总数得点筛选（主动模式）。
118	  function countDeclineBadges(all) {
119	    let n = 0;
120	    for (const e of all) {
121	      const t = (e.textContent || '').trim();
122	      if (!/商品流量近期有下降/.test(t) || t.length > 20) continue;
123	      // 只数最内层节点，避免父容器重复计数
124	      if ([...e.children].some((c) => /商品流量近期有下降/.test(c.textContent || ''))) continue;
125	      const r = e.getBoundingClientRect();
126	      if (r.width > 0 && r.height > 0) n++; // 只数真正渲染出来的行徽标，排除隐藏的筛选项/图例
127	    }
128	    return n;
129	  }
130	  // 扫描当前页商品行：按「SPU ID(=productId)」边界把行分组成商品，
131	  // 识别哪些商品带「商品流量待关注 / 商品流量近期有下降」徽标，取 productId + 商品名 + SKC。
132	  // 局限：只覆盖当前页(默认 20 条/页)，跨页的限流/下降商品扫不到——被动读的固有限制
133	  //（chip 计数 trafficWatch 才是全量总数；这里只为「点名 + 给编辑链接」）。
134	  function scanProducts() {
135	    const rows = [...document.querySelectorAll('[data-testid="beast-core-table-body-tr"]')];
136	    const products = [];
137	    let cur = null;
138	    for (const tr of rows) {
139	      const t = tr.textContent || '';
140	      const spu = t.match(/SPU\s*ID[:：]\s*(\d+)/); // DOM「SPU ID」= API/编辑页的 productId
141	      if (spu) {
142	        // 商品名只在「商品信息」那一格取（含 SPU ID 的 td），排除「标签：值」属性行，取最长一段。
143	        // （曾扫整行 → 第 3 条抓成隔壁「商品属性」列的「主体材质：铝合金」，故限定到该 td。）
144	        const infoTd = [...tr.querySelectorAll('td')].find((td) => /SPU\s*ID/.test(td.textContent || '')) || tr;
145	        const name = [...infoTd.querySelectorAll('*')].map((e) => (e.textContent || '').trim())
146	          .filter((x) => x.length >= 6 && x.length <= 80 && /[一-龥]/.test(x) && !/^.{0,6}[:：]/.test(x) && !/SPU|SKC/.test(x))
147	          .sort((a, b) => b.length - a.length)[0] || '';
148	        cur = { productId: spu[1], skc: (t.match(/SKC\s*ID[:：]\s*(\d+)/) || [])[1] || '', name: name, watch: false, decline: false };
149	        products.push(cur);
150	      }
151	      if (cur) {
152	        if (/商品流量待关注/.test(t)) cur.watch = true;
153	        if (/商品流量近期有下降/.test(t)) cur.decline = true;
154	      }
155	    }
156	    return products;
157	  }
158	  function readTraffic() {
159	    const all = [...document.querySelectorAll('*')];
160	    return {
161	      watch: readChipCount(all, '商品流量待关注'),
162	      decline: countDeclineBadges(all),
163	    };
164	  }
165	  const pickItem = (p) => ({ productId: p.productId, name: p.name, skc: p.skc });
166	  // 常驻轮询：每 2s 读一次 chip 计数 + 扫一次商品明细，但**只在结果变化时上报**
167	  //（靠 dedupe 避免刷爆后台）。这样用户后点「商品流量待关注」筛选/翻页时，
168	  // 明细也会在 2s 内自动刷新——旧版只在加载后 40s 内扫、之后点筛选就不扫了。
169	  let tries = 0;
170	  let lastKey = '';
171	  setInterval(() => {
172	    tries++;
173	    // 商品表格是否已渲染出行——徽标在行里，必须等行出来再扫，否则会在徽标出现前就读成空
174	    const gridReady = !!document.querySelector('[data-testid="beast-core-table-body-tr"]');
175	    const { watch, decline } = readTraffic();
176	    const msg = { type: 'chipStats', store: readStoreName() };
177	    if (watch != null) msg.trafficWatch = watch;
178	    let watchItems = [];
179	    let declineItems = [];
180	    if (gridReady) {
181	      const products = scanProducts();
182	      watchItems = products.filter((p) => p.watch).map(pickItem);
183	      declineItems = products.filter((p) => p.decline).map(pickItem);
184	      msg.trafficDecline = decline; // 仅在表格渲染后 decline 才可信
185	      msg.watchItems = watchItems;
186	      msg.declineItems = declineItems;
187	    }
188	    // 有 count 时等网格就绪再发（尽量带上明细）；网格长时间卡「加载中」(tries>8≈16s)时 count-only 兜底
189	    const readyOrTimedOut = gridReady || tries > 8;
190	    if (!((msg.trafficWatch != null && readyOrTimedOut) || 'trafficDecline' in msg)) return;
191	    // 结果没变化就不重发；变化了（如刚点了筛选、切了店）才上报
192	    const key = JSON.stringify([msg.store, msg.trafficWatch, msg.trafficDecline,
193	      watchItems.map((i) => i.productId), declineItems.map((i) => i.productId)]);
194	    if (key === lastKey) return;
195	    lastKey = key;
196	    LOG.info('Traffic update: watch=' + (watch != null ? watch : 'null') + ' decline=' + (decline != null ? decline : 'null') + ' watchItems=' + watchItems.length + ' declineItems=' + declineItems.length);
197	    try { chrome.runtime.sendMessage(msg); } catch (e) {}
198	  }, 2000);
199	
200	  // ---------- 切店自动化（轮巡用，由后台指令驱动） ----------
201	  async function waitFor(fn, timeout, step) {
202	    const t0 = Date.now();
203	    for (;;) { let r; try { r = fn(); } catch (e) { r = null; } if (r) return r; if (Date.now() - t0 > (timeout || 6000)) return null; await sleep(step || 200); }
204	  }
205	  function textEls(re, maxLen) {
206	    return [...document.querySelectorAll('*')].filter((e) => { const t = (e.textContent || '').trim(); return re.test(t) && t.length <= (maxLen || 40); });
207	  }
208	  function innermost(els) { return els.slice().sort((a, b) => (a.textContent || '').length - (b.textContent || '').length)[0] || null; }
209	  function clickableAncestor(el) { let n = el; for (let i = 0; i < 5 && n; i++) { if (n.tagName === 'BUTTON' || n.tagName === 'A' || n.getAttribute('role') === 'button') return n; n = n.parentElement; } return el; }
210	  // 完整鼠标事件序列（很多组件要 mousedown/up 才触发，单纯 click 不生效）
211	  function realClick(el) {
212	    if (!el) return false;
213	    const opts = { bubbles: true, cancelable: true, view: window };
214	    try { el.scrollIntoView({ block: 'center' }); } catch (e) {}
215	    for (const type of ['pointerdown', 'mousedown', 'mouseup', 'click']) {
216	      try { el.dispatchEvent(new MouseEvent(type, opts)); } catch (e) {}
217	    }
218	    try { el.click(); } catch (e) {}
219	    return true;
220	  }
221	  function modalOpen() { return textEls(/切换店铺|您的账户存在/, 20).length > 0; }
222	  function closeModal() {
223	    const x = document.querySelector('[aria-label="Close"],[aria-label="关闭"],.beast-core-modal-close,.semi-modal-close,.SnowModal_closeIcon');
224	    if (x) { realClick(x); return; }
225	    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
226	  }
227	
228	  // 压缩输出某元素的 HTML 骨架（去 style/data 属性），便于回传诊断
229	  function domSkel(el, maxLen) {
230	    if (!el) return 'null';
231	    let h = (el.outerHTML || '');
232	    h = h.replace(/\s(style|data-[\w-]+|aria-[\w-]+)="[^"]*"/g, '').replace(/>\s+</g, '><').replace(/\s{2,}/g, ' ');
233	    return h.slice(0, maxLen || 2200);
234	  }
235	
236	  function visible(el) { const b = el.getBoundingClientRect(); return b.width > 0 && b.height > 0; }
237	
238	  async function openStoreModal(diag) {
239	    diag = diag || [];
240	    if (modalOpen()) { diag.push('弹窗已开'); return true; }
241	    const nameEl = findStoreNameEl();
242	    diag.push('店名=' + (nameEl ? (nameEl.textContent || '').trim() : 'null'));
243	    if (nameEl) {
244	      // 只点一次触发下拉：点店名的可点祖先 + 店名右侧箭头坐标（避免多次点击把下拉又关掉）
245	      const r = nameEl.getBoundingClientRect();
246	      realClick(clickableAncestor(nameEl));
247	      const el = document.elementFromPoint(Math.min(window.innerWidth - 3, r.right + 14), r.top + r.height / 2);
248	      if (el && el !== nameEl) realClick(el);
249	    }
250	    // 下拉里“切换”按钮：只认可见的、精确文本“切换”，取最后一个（下拉通常在 DOM 靠后）
251	    const sw = await waitFor(() => {
252	      const cands = textEls(/^切换$/, 6).filter(visible);
253	      return cands.length ? clickableAncestor(cands[cands.length - 1]) : null;
254	    }, 3500);
255	    diag.push('下拉切换按钮=' + !!sw);
256	    if (sw) realClick(sw);
257	    const ok = !!(await waitFor(() => (modalOpen() ? true : null), 4500));
258	    diag.push('弹窗打开=' + ok);
259	    if (!ok) {
260	      LOG.warn('Open store modal failed: ' + diag.join(' ; '));
261	      const cands = textEls(/切换/, 8).map((e) => {
262	        const b = e.getBoundingClientRect();
263	        return e.tagName + '.' + String(e.className || '').split(' ')[0] + '[' + (e.textContent || '').trim().slice(0, 6) + ',y' + Math.round(b.top) + ',w' + Math.round(b.width) + ']';
264	      });
265	      diag.push('切换候选(' + cands.length + ')=' + cands.join(' '));
266	      diag.push('模态计数 切换店铺=' + textEls(/切换店铺/, 20).length + ' 您的账户=' + textEls(/您的账户/, 40).length);
267	    }
268	    return ok;
269	  }
270	
271	  async function listStores() {
272	    if (!(await openStoreModal())) return [];
273	    await sleep(500);
274	    // 每个店铺行都带”半托管/全托管”标签；据此定位店名，避开背景页面的杂项英文。
275	    // 额外检查：审核中/已禁用的店铺（如 FashionNest 显示 “application is under review”）
276	    // 没有可用的「切换」按钮，通过判断按钮是否 disabled/aria-disabled 来过滤。
277	    const tags = textEls(/托管/, 6).filter(visible);
278	    const names = [];
279	    for (const tag of tags) {
280	      let row = tag.parentElement;
281	      for (let i = 0; i < 4 && row; i++) {
282	        const en = [...row.querySelectorAll('span,div,p,a')]
283	          .map((e) => (e.textContent || '').trim())
284	          .find((t) => /^[A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,3}$/.test(t) && t.length >= 2 && t.length <= 30 && !/^(NEW|Beta)$/i.test(t));
285	        if (en) {
286	          // 确认该店铺行有可用的「切换」按钮（过滤审核中/已禁用的店）
287	          let container = row;
288	          for (let j = 0; j < 5 && container; j++) {
289	            const switchBtn = [...container.querySelectorAll('button,[role=button]')]
290	              .find((b) => /切换/.test(b.textContent || '') && !b.disabled && b.getAttribute('aria-disabled') !== 'true');
291	            if (switchBtn) { names.push(en); break; }
292	            container = container.parentElement;
293	          }
294	          break;
295	        }
296	        row = row.parentElement;
297	      }
298	    }
299	    closeModal();
300	    const uniq = [...new Set(names)];
301	    LOG.info('listStores: ' + uniq.length + ' stores: ' + uniq.join(', '));
302	    return uniq;
303	  }
304	
305	  async function switchTo(target) {
306	    const diag = [];
307	    if (!(await openStoreModal(diag))) return { ok: false, msg: '打不开弹窗 | ' + diag.join(' ; ') };
308	    await sleep(300);
309	    const esc = String(target).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
310	    const rows = textEls(new RegExp(esc), 120).filter((e) => /切换/.test(e.textContent || ''));
311	    const row = innermost(rows);
312	    if (!row) { closeModal(); return { ok: false, msg: '弹窗里没找到店铺 ' + target }; }
313	    let btn = [...row.querySelectorAll('button,[role=button]')].find((b) => /切换/.test(b.textContent || '') && !b.disabled && b.getAttribute('aria-disabled') !== 'true');
314	    if (!btn) {
315	      const cands = textEls(/^切换$/, 6).map(clickableAncestor).filter((b) => b && !b.disabled);
316	      btn = cands.find((b) => row.contains(b) || (b.compareDocumentPosition(row) & Node.DOCUMENT_POSITION_CONTAINED_BY)) || null;
317	    }
318	    if (!btn) { closeModal(); return { ok: false, msg: '没找到可点的切换按钮(' + target + ')，可能已是当前店' }; }
319	    LOG.info('Switching store to: ' + target);
320	    realClick(btn); // 触发切店（SPA 更新或整页重载）
321	    return { ok: true, msg: '已点击切换到 ' + target };
322	  }
323	
324	  // ---------- 主动捞「商品流量待关注」明细（发现异常时调，点筛选→扫→重置） ----------
325	  // 读列表底部「共有 N 条」（筛选生效后该数=待关注总数）
326	  function readTotalCount() {
327	    const el = [...document.querySelectorAll('*')].find(
328	      (x) => x.children.length === 0 && /共有\s*[\d,]+\s*条/.test(x.textContent || '')
329	    );
330	    if (!el) return null;
331	    const m = (el.textContent || '').match(/共有\s*([\d,]+)\s*条/);
332	    return m ? Number(m[1].replace(/,/g, '')) : null;
333	  }
334	  // 定位「商品流量待关注」快速筛选 chip 容器（与 readChipCount 同一稳定 class 前缀）
335	  function findWatchChip() {
336	    for (const card of document.querySelectorAll('[class*="use-quick-field_tsx_card__"]')) {
337	      if (/商品流量待关注/.test(card.textContent || '')) return card;
338	    }
339	    return null;
340	  }
341	  // 点「重置」清掉快速筛选，恢复用户视图
342	  function clickReset() {
343	    const btn = textEls(/^重置$/, 6).filter(visible)[0];
344	    if (btn) realClick(clickableAncestor(btn));
345	  }
346	  // 点开「商品流量待关注」筛选 → 扫出这几条商品(productId+name+skc) → 重置。
347	  // 筛选生效后网格里每行都是待关注商品，故取全部行（不再依赖行内徽标）。
348	  // 只覆盖筛选后的当前页(默认 20 条)，>20 条的溢出由 total 提示行说明。
349	  async function scanWatchList() {
350	    LOG.info('scanWatchList: scanning...');
351	    const chip = findWatchChip();
352	    if (!chip) { LOG.warn('scanWatchList: chip not found'); return { store: readStoreName(), items: [], applied: false, msg: '未找到待关注筛选 chip' }; }
353	    const before = readTotalCount();
354	    realClick(clickableAncestor(chip));
355	    // 等列表真正刷新：底部「共有 N 条」的数值发生变化（通常变小）才算筛选生效
356	    await waitFor(() => {
357	      const t = readTotalCount();
358	      return (t != null && before != null && t !== before) ? t : null;
359	    }, 8000, 300);
360	    await sleep(1200); // 等筛选后的网格稳定渲染
361	    const after = readTotalCount();
362	    // 仅当确实生效（数值变化且不大于原总数）才采纳，绝不把未筛选的整页当成待关注
363	    const applied = after != null && before != null && after !== before && after <= before;
364	    let items = [];
365	    if (applied) items = scanProducts().map((p) => ({ productId: p.productId, name: p.name, skc: p.skc }));
366	    // 复位（必须彻底清掉筛选，否则会污染随后的在售扫描 → 误报下架）：
367	    //   ① 若已生效，再点一次同一 chip toggle 回未选中（比只点「重置」更精准可靠）；
368	    //   ② 再点「重置」兜底；③ 等「共有 N 条」回升到筛选前的值，确认筛选真的清掉了。
369	    if (applied) realClick(clickableAncestor(chip));
370	    clickReset();
371	    await waitFor(() => {
372	      const t = readTotalCount();
373	      return (t != null && before != null && t >= before) ? t : null;
374	    }, 6000, 300);
375	    await sleep(600);
376	    LOG.info('scanWatchList done: applied=' + applied + ' items=' + items.length + ' total=' + after);
377	    return { store: readStoreName(), items: items, total: after, applied: applied };
378	  }
379	
380	  // 读某个 tab 标签上印的数字（形如「在售中 13」/「全部 214」）。干净无筛选视图下=真实数量。
381	  function readTabCount(re) {
382	    const labels = [...document.querySelectorAll('[data-testid="beast-core-tab-itemLabel"]')].filter(visible);
383	    for (const el of labels) {
384	      const t = (el.textContent || '').trim();
385	      if (re.test(t)) { const m = t.match(/(\d[\d,]*)/); if (m) return Number(m[1].replace(/,/g, '')); }
386	    }
387	    return null;
388	  }
389	  // 扫「在售中」商品清单：先复位到干净视图 → 点在售 tab → 确认视图生效 → scanProducts 取 productId+name+skc。
390	  // 用于 background diff 出"上轮在售、这轮不在"的下架商品。仅轮巡(空闲)时调，扫完点回「全部」。
391	  // ⚠️ 关键①：扫描前**必须**清掉一切快速筛选（尤其「商品流量待关注」）——否则会只扫到筛选后的
392	  //    几条在售商品，误报「下架 N 个」（历史假告警根因）。这里主动复位，不依赖调用时机的干净。
393	  // ⚠️ 关键②：点完「在售中」必须验证视图真的生效（底部「共有 N 条」== tab 上「在售中 N」）再扫。
394	  //    点击可能被切店残留弹窗/背挡拦截，点了 ≠ 生效；若在「全部」「未发布」视图下扫，
395	  //    会混入从未上架的商品写进基准（污染扫描只增不减、当时不告警，悄悄脏掉基准，
396	  //    下一轮干净扫描才引爆「下架15个(在售20→13)」式假告警）。验证不过就放弃本轮——宁可漏一轮，不脏基准。
397	  async function scanOnSaleList() {
398	    LOG.info('scanOnSaleList: scanning...');
399	    const findTab = (re) => {
400	      const labels = [...document.querySelectorAll('[data-testid="beast-core-tab-itemLabel"]')].filter(visible);
401	      return labels.find((e) => re.test((e.textContent || '').trim())) || textEls(re, 14).filter(visible)[0] || null;
402	    };
403	    const backToAll = () => { const t = findTab(/^全部/); if (t) realClick(clickableAncestor(t)); };
404	    // ① 复位到干净、无快速筛选的状态：先回「全部」tab，再点「重置」清掉任何快速筛选 chip。
405	    backToAll();
406	    await sleep(300);
407	    clickReset();
408	    await sleep(1000);
409	    // ② 点「在售中」tab 并等视图生效（底部总数 == 在售 tab 计数）；点击可能被残留弹窗拦截 → 失败重试一次
410	    let tabCount = null;
411	    let viewOk = false;
412	    for (let attempt = 1; attempt <= 2 && !viewOk; attempt++) {
413	      const onSaleTab = findTab(/^在售中/);
414	      if (onSaleTab) realClick(clickableAncestor(onSaleTab));
415	      await waitFor(() => document.querySelector('[data-testid="beast-core-table-body-tr"]'), 8000, 300);
416	      await sleep(1800); // 等在售网格稳定渲染（避免只扫到半页）
417	      tabCount = readTabCount(/^在售中/);
418	      if (tabCount == null) { viewOk = true; break; } // 读不到 tab 数 → 无法交叉验证，放行（后台仍有数量上限兜底）
419	      const ok = await waitFor(() => { const t = readTotalCount(); return (t != null && t === tabCount) ? true : null; }, 6000, 300);
420	      if (ok || readTotalCount() == null) { viewOk = true; break; } // 生效；footer 读不到 → 放行
421	      LOG.warn('scanOnSaleList: 在售视图未生效(第' + attempt + '次) gridTotal=' + readTotalCount() + ' tabCount=' + tabCount);
422	      clickReset();
423	      await sleep(800);
424	    }
425	    if (!viewOk) {
426	      LOG.warn('scanOnSaleList aborted: 在售视图两次都未生效，本轮放弃（不动基准）');
427	      backToAll();
428	      return { store: readStoreName(), items: [], onSaleTabCount: tabCount, msg: '在售视图未生效，本轮放弃扫描' };
429	    }
430	    // ③ 读干净视图下「在售中 N」的真实数字——作为 background 判定"是否扫全/是否被筛选污染"的权威值
431	    const onSaleTabCount = readTabCount(/^在售中/);
432	    const products = scanProducts();
433	    const items = products.map((p) => ({ productId: p.productId, name: p.name, skc: p.skc }));
434	    // ④ 扫到的行数比「在售中 N」还多 = 视图污染（全部/未发布/别店商品混入）→ 放弃，绝不让它进基准
435	    if (onSaleTabCount != null && items.length > onSaleTabCount) {
436	      LOG.warn('scanOnSaleList aborted: scanned=' + items.length + ' > tabCount=' + onSaleTabCount + '（视图污染，本轮放弃）');
437	      backToAll();
438	      return { store: readStoreName(), items: [], onSaleTabCount: onSaleTabCount, msg: '扫描行数超过在售数，疑似视图污染，本轮放弃' };
439	    }
440	    var scanMsg = 'scanOnSale: tabCount=' + onSaleTabCount + ' scanned=' + items.length;
441	    if (items.length && onSaleTabCount && items.length < onSaleTabCount) scanMsg += ' (WARNING: possible page truncation)';
442	    LOG.info(scanMsg);
443	    // 恢复到「全部」tab（轮巡时用户看不到，但保持视图干净）
444	    backToAll();
445	    LOG.info('scanOnSaleList done: items=' + items.length + ' onSaleTabCount=' + onSaleTabCount);
446	    return { store: readStoreName(), items: items, onSaleTabCount: onSaleTabCount };
447	  }
448	
449	  chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
450	    if (!msg || !msg.cmd) return;
451	    (async () => {
452	      try {
453	        if (msg.cmd === 'ping') { sendResponse({ store: readStoreName() }); return; } // 只读，不入锁
454	        if (msg.cmd === 'listStores') { sendResponse({ names: await withLock(listStores) }); return; }
455	        if (msg.cmd === 'switchTo') { sendResponse(await withLock(() => switchTo(msg.target))); return; }
456	        if (msg.cmd === 'scanOnSale') { sendResponse(await withLock(scanOnSaleList)); return; }
457	        if (msg.cmd === 'scanWatchList') { sendResponse(await withLock(scanWatchList)); return; }
458	      } catch (e) { LOG.error('Command handler error: cmd=' + msg.cmd + ' error=' + String((e && e.message) || e)); sendResponse({ ok: false, msg: String((e && e.message) || e) }); }
459	    })();
460	    return true;
461	  });
462	})();
