1	var LOG = TemuLogger.createLogger('popup');
2	
3	function send(type, extra) {
4	  return new Promise((res) => chrome.runtime.sendMessage(Object.assign({ type }, extra), res));
5	}
6	function esc(s) {
7	  return String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
8	}
9	function setMsg(text, cls) {
10	  const el = document.getElementById('msg');
11	  el.textContent = text || '';
12	  el.className = cls || '';
13	}
14	function fmtTs(ts) {
15	  return ts ? new Date(ts).toLocaleString('zh-CN') : '—';
16	}
17	function num(v) { return v != null ? v : '—'; }
18	function editLink(productId) { return 'https://agentseller.temu.com/goods/edit?from=productList&productId=' + productId; }
19	function itemsHtml(items, label, color) {
20	  if (!Array.isArray(items) || !items.length) return '';
21	  return `<div class="items">${esc(label)}${items.map((it) =>
22	    `<a href="${esc(editLink(it.productId))}" target="_blank" style="color:${color}" title="SKC ${esc(it.skc || '-')}">• ${esc((it.name || '商品').slice(0, 22))}</a>`
23	  ).join('')}</div>`;
24	}
25	// 编辑页 parent/list 兜底抓到的扁平规格
26	function skuSpecsHtml(specs) {
27	  if (!Array.isArray(specs) || !specs.length) return '';
28	  const names = specs.map((s) => esc((s.name || 'SKU').slice(0, 20))).join('、');
