1	// Service worker：接收接口数据 → 按【店铺名】分别解析/对比/告警。
2	// 多店铺：同一账号下有多个店(HomeCove/Twilight Cove/Agnis)，切到哪个店就记哪个店，各自独立快照与告警。
3	// 数据只存本机 chrome.storage.local，不上传任何服务器。
4	
5	importScripts('logger.js');
6	var log = TemuLogger.createLogger('bg');
7	
8	const GOODS_URL = 'https://agentseller.temu.com/goods/list';
9	const DEFAULT_CONFIG = {
10	  webhook: '',
11	  intervalMinutes: 15,
12	  enabled: true,
13	  storeName: '',
14	  // 定时必提醒：每天固定时刻强制发飞书状态汇报（无异常也发，证明插件活着）
15	  mustRemindEnabled: true,
16	  mustRemindTimes: ['09:30', '16:30'],
17	  // 前台变体监测
18	  frontCheckEnabled: true,
19	  frontCheckIntervalHours: 3,
20	};
21	const MUST_REMIND_PREFIX = 'mustRemind|';
22	
23	// ---------------- 解析 ----------------
24	function parseCountStatus(body) {
25	  try {
26	    const j = JSON.parse(body);
27	    const list = j && j.result && j.result.skcTopStatusCountList;
28	    if (!Array.isArray(list)) return null;
29	    const pick = (s) => {
30	      const x = list.find((e) => e && e.skcTopStatus === s);
31	      return x && typeof x.skcTotal === 'number' ? x.skcTotal : null;
32	    };
33	    return { onSale: pick(100), unpublished: pick(0), removed: pick(200), deleted: pick(300) };
34	  } catch (e) { log.warn('parseCountStatus: failed to parse response'); return null; }
35	}
36	// 从 productSkuSpecList 拼规格名，如「颜色:Khaki / 数量:1pc」→「Khaki」优先单值，多维用「/」
37	function formatSkuSpecName(sku) {
38	  const specs = (sku && Array.isArray(sku.productSkuSpecList)) ? sku.productSkuSpecList : null;
39	  if (specs && specs.length) {
40	    return specs.map((sp) => String(sp.specName || sp.unitSpecName || '').trim()).filter(Boolean).join('/') || '';
41	  }
42	  return String((sku && (sku.specName || sku.skuName || sku.name)) || '').trim();
43	}
44	// 把单个 SKU 对象规范成统一结构
45	function normalizeSku(sku, product) {
46	  if (!sku || typeof sku !== 'object') return null;
47	  const skuId = sku.productSkuId || sku.skuId || sku.skuIdStr || sku.id || sku.skuSpecId || '';
48	  const name = formatSkuSpecName(sku);
49	  if (!skuId && !name) return null;
50	  return {
51	    skuId: skuId ? String(skuId) : '',
52	    name: name || ('SKU' + (skuId ? ' ' + skuId : '')),
53	    img: sku.thumbUrl || sku.skuImgUrl || sku.imageUrl || sku.imgUrl || '',
54	    productId: product && (product.productId || product.productIdStr) ? String(product.productId || product.productIdStr) : '',
55	    skc: product && (product.productSkcId || product.skcId) ? String(product.productSkcId || product.skcId) : '',
56	    productName: product && product.productName ? String(product.productName) : '',
57	    stock: typeof sku.realStock === 'number' ? sku.realStock
58	      : (typeof sku.virtualStock === 'number' ? sku.virtualStock : null),
59	  };
60	}
61	// 从 pageQuery 商品项提取 SKU 列表（真实字段：productSkuSummaries[].productSkuId + productSkuSpecList）
62	function extractSkusFromProduct(it) {
63	  if (!it || typeof it !== 'object') return [];
64	  const arr = Array.isArray(it.productSkuSummaries) ? it.productSkuSummaries
65	    : (Array.isArray(it.skuList) ? it.skuList
66	      : (Array.isArray(it.productSkus) ? it.productSkus : null));
67	  if (!arr) return [];
68	  return arr.map((sku) => normalizeSku(sku, it)).filter(Boolean);
69	}
70	function parsePageQuery(body) {
71	  try {
72	    const j = JSON.parse(body);
73	    const r = j && j.result;
74	    if (!r) return null;
75	    const pageItems = Array.isArray(r.pageItems) ? r.pageItems
76	      : (Array.isArray(r.list) ? r.list : []);
77	    const products = [];
78	    const flatSkus = [];
79	    for (const it of pageItems) {
80	      if (!it || typeof it !== 'object') continue;
81	      const productId = it.productId != null ? String(it.productId) : '';
82	      if (!productId) continue;
83	      const skus = extractSkusFromProduct(it);
84	      const product = {
85	        productId,
86	        skc: it.productSkcId != null ? String(it.productSkcId) : '',
87	        name: String(it.productName || '').slice(0, 80),
88	        skus,
89	        skuCount: skus.length,
90	      };
91	      products.push(product);
92	      for (const s of skus) flatSkus.push(s);
93	    }
94	    return {
95	      total: typeof r.total === 'number' ? r.total : null,
96	      products,
97	      pageSkus: flatSkus,
98	      pageSkuCount: flatSkus.length,
99	      multiSkuProducts: products.filter((p) => p.skuCount > 1),
100	    };
101	  } catch (e) { log.warn('parsePageQuery: failed to parse response'); return null; }
102	}
103	// 在未知 JSON 树里找「看起来像 SKU 列表」的数组（编辑页 parent/list 结构会漂移）
104	function findSkuLikeArray(node, depth) {
105	  if (depth > 6 || node == null) return null;
106	  if (Array.isArray(node)) {
107	    if (!node.length) return null;
108	    const sample = node.slice(0, 5).filter((x) => x && typeof x === 'object');
109	    if (sample.length && sample.every((x) =>
110	      x.productSkuId != null || x.skuId != null || x.productSkuSpecList != null
111	      || x.specName != null || x.skuSpecId != null)) {
112	      return node;
113	    }
114	    for (const el of node.slice(0, 20)) {
115	      const found = findSkuLikeArray(el, depth + 1);
116	      if (found) return found;
117	    }
118	    return null;
119	  }
120	  if (typeof node === 'object') {
121	    // 优先常见键
122	    for (const k of ['list', 'skuSpecList', 'skuSpecs', 'productSkuSummaries', 'skuList', 'data', 'records', 'items']) {
123	      if (Array.isArray(node[k])) {
124	        const found = findSkuLikeArray(node[k], depth + 1);
125	        if (found) return found;
126	      }
127	    }
128	    for (const k of Object.keys(node).slice(0, 30)) {
129	      const found = findSkuLikeArray(node[k], depth + 1);
130	      if (found) return found;
131	    }
132	  }
133	  return null;
134	}
135	function parseSkuSpecList(body) {
136	  try {
137	    const j = JSON.parse(body);
138	    // 1) 浅路径 2) 深搜「SKU 形」数组
139	    let list = j && j.result && j.result.list;
140	    if (!Array.isArray(list)) list = j && j.result && j.result.skuSpecList;
141	    if (!Array.isArray(list)) list = j && j.result && j.result.skuSpecs;
142	    if (!Array.isArray(list)) list = j && j.result && j.result.productSkuSummaries;
143	    if (!Array.isArray(list)) list = j && j.result && j.result.data;
144	    if (!Array.isArray(list)) list = j && j.result && Array.isArray(j.result) ? j.result : null;
145	    if (!Array.isArray(list)) list = j && j.data && j.data.list;
146	    if (!Array.isArray(list)) list = j && Array.isArray(j.data) ? j.data : null;
147	    if (!Array.isArray(list)) list = findSkuLikeArray(j, 0);
148	    if (!Array.isArray(list)) {
149	      log.warn('parseSkuSpecList: no sku-like array, result keys=' +
150	        (j && j.result ? Object.keys(j.result).slice(0, 12).join(',') : 'null'));
151	      chrome.storage.local.set({ lastSkuSpecRawFail: body.slice(0, 3000) });
152	      return null;
153	    }
154	    const specs = list.map((it) => normalizeSku(it, null)).filter(Boolean);
155	    if (!specs.length) {
156	      log.warn('parseSkuSpecList: parsed ' + list.length + ' items but none had skuId/name, first item keys=' +
157	        (list[0] && typeof list[0] === 'object' ? Object.keys(list[0]).slice(0, 12).join(',') : typeof list[0]));
158	      chrome.storage.local.set({ lastSkuSpecRawFail: body.slice(0, 3000) });
159	      return null;
160	    }
161	    return { skuSpecs: specs, skuSpecCount: specs.length };
162	  } catch (e) { log.warn('parseSkuSpecList: failed to parse response: ' + (e && e.message ? e.message : String(e))); return null; }
163	}
164	function parseSkuPriceQuery(body) {
165	  try {
166	    const j = JSON.parse(body);
167	    const r = j && j.result;
168	    if (!r) return null;
169	    // 数据结构未知，先整体保存，后续按需解析
170	    return { skuPriceRaw: r };
171	  } catch (e) { log.warn('parseSkuPriceQuery: failed to parse response'); return null; }
172	}
