174	// ---------------- 存取 ----------------
175	async function getConfig() {
176	  const { config } = await chrome.storage.local.get('config');
177	  return Object.assign({}, DEFAULT_CONFIG, config || {});
178	}
179	async function getStores() {
180	  const { stores } = await chrome.storage.local.get('stores');
181	  return stores || {};
182	}
183	async function saveStores(stores) {
184	  await chrome.storage.local.set({ stores });
185	}
186	// 更新某店的最新读数
187	async function updateStoreLatest(name, patch) {
188	  const stores = await getStores();
189	  const s = stores[name] || { latest: {}, snapshot: {} };
190	  s.latest = Object.assign({}, s.latest, patch, { ts: Date.now() });
191	  stores[name] = s;
192	  await saveStores(stores);
193	  return s;
194	}
