416	  let compared = 0;
417	
418	  for (const p of products) {
419	    if (!p || !p.productId) continue;
420	    const pid = String(p.productId);
421	    const currSkus = Array.isArray(p.skus) ? p.skus : [];
422	    // 当前商品在本页出现但 SKU 列表空：可能接口字段漂移/截断，跳过该商品、保留旧基准
423	    if (!currSkus.length) continue;
424	    const currById = {};
425	    for (const sk of currSkus) {
426	      if (sk && sk.skuId) currById[String(sk.skuId)] = sk;
427	    }
428	    const prev = prevMap[pid];
429	    if (prev && prev.skus && typeof prev.skus === 'object') {
430	      compared += 1;
431	      for (const skuId of Object.keys(prev.skus)) {
432	        if (!currById[skuId]) {
433	          const old = prev.skus[skuId] || {};
434	          removed.push({
435	            productId: pid,
436	            productName: p.name || prev.name || '',
437	            skc: p.skc || prev.skc || '',
438	            skuId,
439	            name: old.name || skuId,
440	          });
441	        }
442	      }
443	    }
444	    // 更新该 product 的 SKU 基准（只记 id→name）
445	    const skusObj = {};
446	    for (const sk of currSkus) {
447	      if (sk && sk.skuId) skusObj[String(sk.skuId)] = { name: sk.name || '', img: sk.img || '' };
448	    }
449	    nextMap[pid] = {
450	      name: p.name || (prev && prev.name) || '',
451	      skc: p.skc || (prev && prev.skc) || '',
452	      skus: skusObj,
453	      ts: Date.now(),
