457	  // 写回快照（合并式：本页商品更新，其它页旧基准保留）
458	  // 重新读 stores 避免覆盖并发写入
459	  const stores2 = await getStores();
460	  const s2 = stores2[name] || s;
461	  s2.snapshot = Object.assign({}, s2.snapshot || {}, { productSkuMap: nextMap });
462	  stores2[name] = s2;
463	  await saveStores(stores2);
464	
465	  if (!removed.length) {
466	    if (compared) log.info('diffProductSkus: store=' + name + ' compared=' + compared + ' removed=0');
467	    return 0;
468	  }
469	
470	  log.info('diffProductSkus: store=' + name + ' compared=' + compared + ' removed=' + removed.length);
471	  if (!cfg.enabled) return removed.length;
472	
473	  const lines = [
474	    '**🏬 ' + name + '**',
475	    '📦 后台检测到 SKU 规格消失 **' + removed.length + '** 个（同商品内对比，非整 SKC 下架）',
476	    '',
477	  ];
478	  // 按商品分组展示
479	  const byProduct = {};
480	  for (const r of removed) {
481	    const k = r.productId;
482	    if (!byProduct[k]) byProduct[k] = { productId: k, productName: r.productName, skc: r.skc, skus: [] };
483	    byProduct[k].skus.push(r);
484	  }
485	  for (const g of Object.values(byProduct)) {
486	    const nm = String(g.productName || '商品').replace(/[[\]]/g, '').slice(0, 30);
487	    lines.push('• [' + nm + '](' + editLink(g.productId) + ')' + (g.skc ? '  SKC ' + g.skc : ''));
488	    for (const sk of g.skus) {
