502	// 在售清单 diff：找出「上一轮在售、这一轮不在」的商品 = 下架/移出在售，带商品名+编辑链接告警。
503	// items 为 content.js 扫「在售中」tab 得到的当前在售商品(productId+name+skc)。返回下架数量(供日志)。
504	// scanStore 为扫描瞬间页面实际所在店：与 name 不符 = 切店竞态（这批是别店数据）→ 整轮作废。
505	async function diffOnSale(name, items, onSaleTabCount, scanStore) {
506	  if (!Array.isArray(items) || !items.length) return 0; // 空 = 扫描失败或真 0，稳妥起见不动基准、不报
507	  if (scanStore && scanStore !== name) { log.warn('onSale scan store mismatch: want=' + name + ' got=' + scanStore + '，本轮作废'); return 0; }
508	  const cfg = await getConfig();
509	  const stores = await getStores();
510	  const s = stores[name] || { latest: {}, snapshot: {} };
511	  // 防残缺扫描/筛选污染误判：以"扫描当时在干净视图下读到的「在售中 N」"为权威在售数
512	  // （content.js scanOnSaleList 复位后读的，不会被「商品流量待关注」筛选污染）；
513	  // 读不到才回退 countStatus 的 latest.onSale。扫到的商品数必须恰好等于它：
514	  //   少了 = 没扫全/分页 → 跳过；多了 = 视图污染（全部/未发布/别店商品混入，可能含从未上架商品）→ 跳过。
515	  //   旧版只查"少"不查"多"，曾放过 20 条污染扫描（在售实为 13）写进基准，
516	  //   下一轮干净扫描引爆「下架15个(在售20→13)」假告警。
517	  const known = (typeof onSaleTabCount === 'number' && onSaleTabCount > 0)
518	    ? onSaleTabCount
519	    : (s.latest && typeof s.latest.onSale === 'number' ? s.latest.onSale : null);
520	  if (known != null && items.length < known) { log.warn('onSale scan incomplete: store=' + name + ' scanned=' + items.length + ' known=' + known); return 0; }
521	  if (known != null && items.length > known) { log.warn('onSale scan overflow: store=' + name + ' scanned=' + items.length + ' known=' + known + '，疑似视图污染，本轮作废'); return 0; }
522	  const newMap = {};
523	  for (const it of items) if (it && it.productId) newMap[it.productId] = { name: it.name || '', skc: it.skc || '' };
524	  const prevMap = s.snapshot && s.snapshot.onSaleIds;
525	  let delistedCount = 0;
526	  if (prevMap && cfg.enabled) { // 首次无基准 → 只记录不报
527	    const delisted = Object.keys(prevMap).filter((pid) => !(pid in newMap));
528	    delistedCount = delisted.length;
529	    if (delisted.length) {
530	      const added = Object.keys(newMap).filter((pid) => !(pid in prevMap)).length;
531	      log.warn('Delisted items: store=' + name + ' count=' + delisted.length + ' onSale=' + Object.keys(prevMap).length + '→' + items.length + ' added=' + added);
532	      const its = delisted.map((pid) => ({ productId: pid, name: prevMap[pid].name, skc: prevMap[pid].skc }));
533	      // 「在售 A → B」的差值 ≠ 下架数（同期可能有新品上架）；补上新增数让账算得平：A - 下架 + 新增 = B
534	      const lines = [`**🏬 ${name}**`, `📉 在售商品下架 ${delisted.length} 个（在售 ${Object.keys(prevMap).length} → ${items.length}${added ? `，同期新增上架 ${added} 个` : ''}）:`,
535	        ...itemLines(its, null), '', `_检查时间：${new Date().toLocaleString('zh-CN')}_`];
536	      const r = await sendFeishu(cfg.webhook, '🔔 Temu 店铺监测告警', lines);
537	      await chrome.storage.local.set({ lastAlert: { ts: Date.now(), ok: r.ok, msg: r.msg, store: name, lines } });
538	    }
539	  } else {
540	    log.info('First onSale baseline: store=' + name + ' items=' + items.length);
541	  }
542	  // 重新取一次 stores 再写：_diffAndAlert 可能在 diffOnSale 处理期间并发更新过 snapshot 的
543	  // 数值字段（onSale/trafficWatch 等），直接用初始读到的 s 会覆盖掉这些更新 → 基准腐败 → "数据后来不准"。
544	  const stores2 = await getStores();
545	  const s2 = stores2[name] || s;
546	  s2.snapshot = Object.assign({}, s2.snapshot || s.snapshot, { onSaleIds: newMap, onSaleIdsTs: Date.now() });
547	  stores2[name] = s2;
548	  await saveStores(stores2);
549	  return delistedCount;
550	}
