552	// 假店名（颜色/规格）黑名单——与 content.js 同步，双重防护
553	// 历史污染：Beige/Black/Charcoal/Grey/Rustic Brown/White Grey/Black Grey 等被误建成「店」
554	const FAKE_STORE_WORDS = /^(black|white|grey|gray|beige|brown|charcoal|red|blue|green|pink|purple|yellow|orange|gold|silver|ivory|cream|navy|olive|tan|khaki|maroon|coral|mint|teal|cyan|magenta|wine|rose|nude|camel|sand|stone|rustic|dark|light|natural|clear|multi|assorted|random|one size|os|xs|s|m|l|xl|xxl|xxxl|sku|skc|spu|usd|cny|eur|gbp|new|beta|seller|central|best|english|chinese|all|more|less|edit|save|submit|cancel|close|next|prev|back|home|cart|account|login|sign|menu|search|help|support|local|warehouse|free|shipping|sale|off|pack|size|color|colour|style|qty|quantity|option|select)$/i;
555	function isFakeStoreName(t) {
556	  if (!t) return true;
557	  const s = String(t).trim();
558	  if (s.length < 2 || s.length > 30) return true;
559	  if (/^[A-Z0-9]+$/.test(s)) return true;
560	  if (/^(Seller Central|Beta|NEW|SKC|SKU|USD|Best Seller|当前店铺)$/i.test(s)) return true;
561	  const words = s.split(/\s+/);
562	  if (words.every((w) => FAKE_STORE_WORDS.test(w))) return true;
563	  if (words.length === 1 && FAKE_STORE_WORDS.test(words[0])) return true;
564	  return false;
565	}
566	// 解析店铺名：优先页面读到的真店名；拒绝颜色/规格假名；读不到才回退
567	async function resolveStore(msgStore) {
568	  if (msgStore && String(msgStore).trim()) {
569	    const n = String(msgStore).trim();
570	    if (!isFakeStoreName(n)) return n;
571	    log.warn('Rejected fake store name: ' + n);
572	  }
573	  // 回退：仅当 storage 里只有 1 个真店时用它；否则用配置名；再否则 null（调用方跳过写入）
574	  const stores = await getStores();
575	  const known = Object.keys(stores).filter((n) => n && !isFakeStoreName(n));
576	  if (known.length === 1) return known[0];
577	  const cfg = await getConfig();
578	  if (cfg.storeName && cfg.storeName.trim() && !isFakeStoreName(cfg.storeName)) return cfg.storeName.trim();
579	  return null;
580	}
581	// 启动/重载时清掉历史误建的假店
582	async function cleanupFakeStores() {
583	  const stores = await getStores();
584	  const fake = Object.keys(stores).filter(isFakeStoreName);
585	  if (!fake.length) return;
586	  for (const n of fake) delete stores[n];
587	  await saveStores(stores);
588	  // 同步清 productUrls 里挂在假店下的链接（挪不了，直接丢）
589	  const cfg = await getConfig();
590	  if (cfg.productUrls) {
591	    let changed = false;
592	    for (const n of fake) {
593	      if (cfg.productUrls[n]) { delete cfg.productUrls[n]; changed = true; }
594	    }
595	    if (changed) await chrome.storage.local.set({ config: cfg });
596	  }
597	  log.warn('Cleaned up fake stores: ' + fake.join(', '));
598	}
