708	          if (!prevG) continue;
709	          const prevNames = new Set((prevG.options || []).filter((o) => !o.disabled).map((o) => o.name));
710	          const currNames = new Set((g.options || []).filter((o) => !o.disabled).map((o) => o.name));
711	          const added = [...currNames].filter((n) => !prevNames.has(n));
712	          const removed = [...prevNames].filter((n) => !currNames.has(n));
713	          if (added.length) changes.push('➕ ' + g.group + ' 新增：' + added.join('、'));
714	          if (removed.length) changes.push('❌ ' + g.group + ' 下架/缺货：' + removed.join('、'));
715	        }
716	        if (prev.price && d.price && prev.price !== d.price) {
717	          changes.push('💰 价格变化：' + prev.price + ' → ' + d.price);
718	        }
719	      } else if (prev) {
720	        log.info('FrontSnapshot first diff baseline: store=' + store + ' url=' + key);
721	      }
722	      // update snapshot
723	      s.frontSnapshot[key] = Object.assign({}, s.frontLatest[key]);
724	      stores[store] = s;
725	      await saveStores(stores);
726	      if (changes.length > 0) {
727	        log.info('FrontAlert: store=' + store + ' url=' + key + ' changes=' + changes.length);
728	        const lines = ['**🏬 ' + store + ' 前台变体变化**',
729	          '商品：[' + (d.title || key) + '](' + (d.fullUrl || key) + ')',
730	          '', ...changes, '',
731	          '_检测时间：' + new Date().toLocaleString('zh-CN') + '_'];
732	        const r = await sendFeishu(cfg.webhook, '🔔 Temu 前台变体监测', lines, 'orange');
733	        await chrome.storage.local.set({ lastFrontAlert: { ts: Date.now(), ok: r.ok, store, url: key, changes } });
734	      }
735	      sendResponse({ ok: true, store, changes });
736	      return;
737	    }
738	    if (msg.type === 'addProductUrl') {
739	      const name = (msg.store || '').trim();
740	      const url = (msg.url || '').trim();
741	      if (!name || !url) { sendResponse({ ok: false, msg: '店铺名和链接不能为空' }); return; }
742	      const cfg = await getConfig();
743	      const productUrls = Object.assign({}, cfg.productUrls || {});
744	      if (!productUrls[name]) productUrls[name] = [];
745	      const base = url.split('?')[0];
746	      if (!productUrls[name].includes(base)) {
747	        productUrls[name].push(base);
748	        cfg.productUrls = productUrls;
749	        await chrome.storage.local.set({ config: cfg });
750	        log.info('ProductUrl added: store=' + name + ' url=' + base);
751	        sendResponse({ ok: true, msg: '已添加', url: base });
752	      } else {
753	        sendResponse({ ok: false, msg: '该链接已存在' });
754	      }
755	      return;
756	    }
757	    if (msg.type === 'deleteProductUrl') {
758	      const name = (msg.store || '').trim();
759	      const url = (msg.url || '').trim();
760	      const cfg = await getConfig();
761	      const productUrls = Object.assign({}, cfg.productUrls || {});
762	      if (productUrls[name]) {
763	        productUrls[name] = productUrls[name].filter((u) => u !== url);
764	        if (!productUrls[name].length) delete productUrls[name];
765	        cfg.productUrls = productUrls;
766	        await chrome.storage.local.set({ config: cfg });
767	        const stores = await getStores();
768	        const s = stores[name];
769	        if (s) {
770	          if (s.frontLatest && s.frontLatest[url]) delete s.frontLatest[url];
771	          if (s.frontSnapshot && s.frontSnapshot[url]) delete s.frontSnapshot[url];
772	          await saveStores(stores);
773	        }
774	        log.info('ProductUrl deleted: store=' + name);
775	        sendResponse({ ok: true, msg: '已删除' });
776	      } else { sendResponse({ ok: false, msg: '店铺不存在' }); }
777	      return;
778	    }
