780	      const { store, url } = msg;
781	      if (!url) { sendResponse({ ok: false, msg: 'URL 不能为空' }); return; }
782	      log.info('FrontCheck manual: store=' + store + ' url=' + url);
783	      let tab = null;
784	      try {
785	        const tabs = await chrome.tabs.query({ url: 'https://www.temu.com/*' });
786	        tab = tabs.find((t) => {
787	          return ((t.url || '').split('?')[0]) === ((url || '').split('?')[0]);
788	        }) || null;
789	      } catch (e) {}
790	      if (tab) {
