795	          const newTab = await chrome.tabs.create({ url, active: false });
796	          await sleep(8000);
797	          const stores2 = await getStores();
798	          const ss = stores2[store];
799	          const key = (url || '').split('?')[0];
800	          const got = ss && ss.frontLatest && ss.frontLatest[key];
801	          try { await chrome.tabs.remove(newTab.id); } catch (e) {}
802	          if (got) {
803	            sendResponse({ ok: true, msg: '已捕获：' + (got.title || key).slice(0, 40) + '，' + got.totalOptions + ' 个变体' });
804	          } else {
805	            sendResponse({ ok: false, msg: '未能提取变体（可能是反爬拦截）。请手动打开商品页后再试。' });
806	          }
807	        } catch (e) {
808	          sendResponse({ ok: false, msg: '打开页面失败：' + (e && e.message || '') });
809	        }
810	      }
811	      return;
812	    }
813	    if (msg.type === 'cycleFrontNow') {
814	      log.info('Manual front cycle requested');
815	      sendResponse({ ok: true, msg: '前台变体轮巡已启动' });
816	      cycleFrontProducts('manual'); // fire-and-forget，不阻塞 sendResponse
817	      return;
818	    }
819	    if (msg.type === 'chipStats') {
820	      const patch = {};
821	      if (typeof msg.trafficWatch === 'number') patch.trafficWatch = msg.trafficWatch;
822	      if (typeof msg.trafficDecline === 'number') patch.trafficDecline = msg.trafficDecline;
823	      if (Array.isArray(msg.watchItems)) patch.watchItems = msg.watchItems;
824	      if (Array.isArray(msg.declineItems)) patch.declineItems = msg.declineItems;
825	      if (Object.keys(patch).length) {
