829	        } else {
830	          log.info('ChipStats: store=' + name + ' trafficWatch=' + (msg.trafficWatch != null ? msg.trafficWatch : 'null') + ' trafficDecline=' + (msg.trafficDecline != null ? msg.trafficDecline : 'null'));
831	          await updateStoreLatest(name, patch);
832	          await diffAndAlert(name);
833	        }
834	      }
835	      sendResponse({ ok: true });
836	      return;
837	    }
838	    if (msg.type === 'getStatus') {
839	      sendResponse({
840	        bgVersion: 'v13-后台SKU规格',
841	        config: await getConfig(),
842	        stores: await getStores(),
843	        ...(await chrome.storage.local.get(['lastAlert', 'lastCycle', 'lastMustRemind', 'lastFrontCycle', 'lastPageSkuSample', 'lastSkuSpecRaw', 'lastSkuSpecRawFail'])),
844	      });
845	      return;
846	    }
847	    if (msg.type === 'addStore') {
848	      const name = (msg.name || '').trim();
849	      log.info('Add store: ' + name);
850	      if (!name) { sendResponse({ ok: false, msg: '店铺名不能为空' }); return; }
851	      if (isFakeStoreName(name)) { sendResponse({ ok: false, msg: '「' + name + '」看起来像颜色/规格名，不是店铺名' }); return; }
852	      const stores = await getStores();
853	      if (stores[name]) { sendResponse({ ok: false, msg: '「' + name + '」已存在' }); return; }
854	      stores[name] = { latest: {}, snapshot: {} };
855	      await saveStores(stores);
856	      sendResponse({ ok: true, msg: '已添加「' + name + '」，下次轮巡将尝试切到该店抓数' });
857	      return;
858	    }
859	    if (msg.type === 'deleteStore') {
860	      const name = (msg.name || '').trim();
861	      log.info('Delete store: ' + name);
862	      const stores = await getStores();
863	      if (!stores[name]) { sendResponse({ ok: false, msg: '「' + name + '」不存在' }); return; }
864	      delete stores[name];
865	      await saveStores(stores);
866	      sendResponse({ ok: true, msg: '已删除「' + name + '」' });
867	      return;
868	    }
869	    if (msg.type === 'checkNow') {
870	      log.info('Manual check requested');
871	      sendResponse(await pollNow());
872	      return;
873	    }
874	    if (msg.type === 'cycleNow') {
875	      log.info('Manual cycle requested');
876	      sendResponse(await cycleStores('manual'));
877	      return;
878	    }
879	    if (msg.type === 'testFeishu') {
880	      log.info('Test Feishu requested');
881	      const cfg = await getConfig();
882	      const r = await sendFeishu(cfg.webhook, '✅ Temu 监测测试', ['这是一条测试消息，收到说明飞书配置正常。', '', `_${new Date().toLocaleString('zh-CN')}_`], 'green');
883	      sendResponse(r);
884	      return;
