899	// ---------------- 自动轮巡（切遍每个店抓数，再切回原店；仅空闲时触发） ----------------
900	const IDLE_SECONDS = 240; // 无操作 4 分钟视为空闲
901	let cycling = false;
902	
903	async function getGoodsTab() {
904	  const tabs = await chrome.tabs.query({ url: 'https://agentseller.temu.com/*' });
905	  return tabs.find((t) => /goods\/list/.test(t.url || '')) || tabs[0] || null;
906	}
907	function sendTab(tabId, cmd) {
908	  return new Promise((resolve) => {
909	    try {
910	      chrome.tabs.sendMessage(tabId, cmd, (resp) => {
911	        if (chrome.runtime.lastError) resolve(null); else resolve(resp);
912	      });
913	    } catch (e) { resolve(null); }
914	  });
915	}
916	async function sendTabRetry(tabId, cmd, tries) {
917	  for (let i = 0; i < (tries || 8); i++) {
918	    const r = await sendTab(tabId, cmd);
919	    if (r) return r;
920	    await new Promise((res) => setTimeout(res, 1000)); // 页面重载后 content 未就绪，重试
921	  }
922	  return null;
923	}
924	function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }
925	// 等某店在切换后被重新抓到（latest.ts 比切换前更新、且有 onSale）
926	async function waitForStoreCapture(name, sinceTs, timeout) {
927	  const t0 = Date.now();
928	  while (Date.now() - t0 < (timeout || 25000)) {
929	    const stores = await getStores();
930	    const L = stores[name] && stores[name].latest;
931	    if (L && typeof L.onSale === 'number' && (L.ts || 0) > sinceTs) return true;
932	    await sleep(1500);
933	  }
934	  return false;
935	}
