937	async function cycleStores(reason) {
938	  if (cycling) return { ok: false, msg: '轮巡进行中' };
939	  cycling = true;
940	  log.info('Cycle started: reason=' + reason);
941	  const cycleLog = [];
942	  try {
943	    const tab = await getGoodsTab();
944	    if (!tab) { log.warn('Cycle: no goods tab found'); return { ok: false, msg: '没有打开的 Temu 商品页' }; }
945	    const cur = await sendTabRetry(tab.id, { cmd: 'ping' }, 5);
946	    const original = cur && cur.store;
947	    cycleLog.push('当前店：' + (original || '未知'));
948	
949	    // 店铺清单：优先用”已知店”（之前逛各店时按顶栏店名记下的，干净准确）；
950	    // 不足 2 个才去弹窗探测（探测会混入页面杂项英文，仅作兜底）。
951	    // 过滤假店名（颜色/规格被误读写进 storage 的）
952	    const known = Object.keys(await getStores()).filter((n) => n && !isFakeStoreName(n));
953	    let names;
954	    if (known.length >= 2) {
955	      names = known;
956	      cycleLog.push('店铺(已知)：' + names.join(', '));
957	    } else {
958	      const listed = await sendTabRetry(tab.id, { cmd: 'listStores' }, 5);
959	      names = [...new Set([...((listed && listed.names) || []), ...known])].filter(Boolean);
960	      cycleLog.push('店铺(探测)：' + names.join(', '));
961	    }
962	    if (names.length === 0) { log.warn('Cycle: no stores identified'); return { ok: false, msg: '没识别到店铺清单' }; }
963	    log.info('Cycle stores: ' + names.length + ' stores: ' + names.join(', '));
964	
965	    for (const name of names) {
966	      if (name === original) continue; // 原店最后再确认；先切别的
967	      const since = Date.now();
968	      const r = await sendTabRetry(tab.id, { cmd: 'switchTo', target: name }, 5);
969	      if (!r || !r.ok) { log.warn('Cycle switch FAILED: store=' + name); cycleLog.push('切到 ' + name + ' 失败：' + (r && r.msg)); continue; }
970	      const got = await waitForStoreCapture(name, since, 25000);
971	      cycleLog.push((got ? '✓ ' : '✗ ') + name);
972	      if (got) {
973	        log.info('Cycle captured: store=' + name);
974	      } else {
975	        log.warn('Cycle capture TIMEOUT: store=' + name);
976	      }
977	      // 扫在售清单 → diff 出下架商品（带链接告警）；os.store 用于校验扫描时页面确实在目标店
978	      if (got) {
979	        const os = await sendTabRetry(tab.id, { cmd: 'scanOnSale' }, 3);
980	        if (os && os.msg) log.warn('scanOnSale aborted: store=' + name + ' ' + os.msg);
981	        if (os && Array.isArray(os.items)) { const d = await diffOnSale(name, os.items, os.onSaleTabCount, os.store); if (d) { log.warn('Cycle delisted: store=' + name + ' count=' + d); cycleLog.push('  ↳下架' + d + '个'); } }
982	      }
983	    }
984	    // 切回原店
985	    if (original) {
986	      const since = Date.now();
987	      await sendTabRetry(tab.id, { cmd: 'switchTo', target: original }, 5);
988	      const gotBack = await waitForStoreCapture(original, since, 25000);
989	      if (gotBack) {
990	        const os = await sendTabRetry(tab.id, { cmd: 'scanOnSale' }, 3);
991	        if (os && os.msg) log.warn('scanOnSale aborted: store=' + original + ' ' + os.msg);
992	        if (os && Array.isArray(os.items)) { const d = await diffOnSale(original, os.items, os.onSaleTabCount, os.store); if (d) cycleLog.push('  ↳' + original + '下架' + d + '个'); }
993	      }
994	      cycleLog.push('已切回 ' + original);
995	    }
996	    const summary = cycleLog.join(' | ');
997	    log.info('Cycle completed: ' + summary);
998	    await chrome.storage.local.set({ lastCycle: { ts: Date.now(), reason, summary } });
999	    return { ok: true, msg: summary };
1000	  } catch (e) {
1001	    log.error('Cycle error: ' + (e && e.message ? e.message : String(e)));
1002	    throw e;
1003	  } finally { cycling = false; }
1004	}
