1006	async function pollNow() {
1007	  log.info('Poll: reloading goods list page');
1008	  const tab = await getGoodsTab();
1009	  if (!tab) { log.warn('Poll: no goods tab found'); return { ok: false, msg: '未找到打开的 Temu 后台标签页，请先登录并打开商品列表页' }; }
1010	  if (/goods\/list/.test(tab.url || '')) { await chrome.tabs.reload(tab.id, { bypassCache: false }); return { ok: true, msg: '已刷新后台商品页' }; }
1011	  await chrome.tabs.update(tab.id, { url: GOODS_URL });
1012	  return { ok: true, msg: '已导航到商品列表页' };
1013	}
