1015	// ---------------- 前台商品页变体轮巡 ----------------
1016	let frontCycling = false;
1017	async function cycleFrontProducts(reason) {
1018	  if (frontCycling) { log.info('FrontCycle skipped: already running'); return; }
1019	  frontCycling = true;
1020	  log.info('FrontCycle started: reason=' + reason);
1021	  try {
1022	    const cfg = await getConfig();
1023	    const productUrls = cfg.productUrls || {};
1024	    const allUrls = [];
1025	    for (const [store, urls] of Object.entries(productUrls)) {
1026	      if (!Array.isArray(urls)) continue;
1027	      for (const url of urls) allUrls.push({ store, url });
1028	    }
1029	    if (!allUrls.length) { log.info('FrontCycle: no URLs configured'); return; }
1030	    log.info('FrontCycle: checking ' + allUrls.length + ' URLs across ' + Object.keys(productUrls).length + ' stores');
1031	
1032	    let checked = 0;
1033	    for (const { store, url } of allUrls) {
1034	      try {
1035	        let tab = null;
1036	        try {
1037	          const tabs = await chrome.tabs.query({ url: 'https://www.temu.com/*' });
1038	          tab = tabs.find((t) => ((t.url || '').split('?')[0]) === url) || null;
1039	        } catch (e) { /* ignore */ }
1040	
1041	        if (tab) {
1042	          log.info('FrontCycle: reusing tab for ' + url.slice(0, 60));
1043	          await sendTabRetry(tab.id, { cmd: 'frontCheck' }, 3);
1044	          await sleep(6000); // 等 content-front 解析+上报
1045	        } else {
1046	          log.info('FrontCycle: opening tab for ' + url.slice(0, 60));
1047	          const newTab = await chrome.tabs.create({ url, active: false });
1048	          await sleep(12000); // 等 SPA 渲染(2.5s) + 解析 + 上报，留足余量
1049	          try { await chrome.tabs.remove(newTab.id); } catch (e) { /* ignore */ }
1050	        }
1051	        checked++;
1052	      } catch (e) {
1053	        log.warn('FrontCycle: error checking ' + url.slice(0, 60) + ': ' + (e && e.message || e));
1054	      }
1055	    }
1056	    log.info('FrontCycle completed: checked=' + checked + '/' + allUrls.length);
1057	    await chrome.storage.local.set({ lastFrontCycle: { ts: Date.now(), reason, checked, total: allUrls.length } });
1058	  } catch (e) {
1059	    log.error('FrontCycle error: ' + (e && e.message ? e.message : String(e)));
1060	  } finally { frontCycling = false; }
1061	}
1062	
1063	// 定时：空闲则轮巡所有店，否则不打扰（靠随看随记覆盖当前店）
1064	// 必提醒：每天固定时刻强制发状态汇报（无异常也发）
1065	chrome.alarms.onAlarm.addListener((a) => {
1066	  log.info('Alarm fired: ' + a.name);
1067	  if (a.name === 'poll') {
1068	    chrome.idle.queryState(IDLE_SECONDS, (state) => {
1069	      if (state === 'idle' || state === 'locked') {
1070	        log.info('System idle, starting automatic cycle');
1071	        cycleStores('idle');
1072	      } else {
1073	        log.info('System active, skipping automatic cycle');
1074	      }
1075	    });
1076	    return;
1077	  }
1078	  if (a.name.startsWith(MUST_REMIND_PREFIX)) {
1079	    const slot = a.name.slice(MUST_REMIND_PREFIX.length);
1080	    // chrome.alarms 的 when 是一次性的 → 发完立刻重排下一天同一时刻
1081	    (async () => {
1082	      try {
1083	        await sendMustRemind(slot);
1084	      } catch (e) {
1085	        log.error('MustRemind error: ' + (e && e.message ? e.message : String(e)));
1086	      } finally {
1087	        await setupMustRemindAlarms();
1088	      }
1089	    })();
1090	    return;
1091	  }
1092	  if (a.name === 'frontPoll') {
1093	    log.info('FrontPoll alarm fired');
1094	    cycleFrontProducts('scheduled');
1095	  }
1096	});
1097	
1098	async function setupAlarm() {
1099	  await chrome.storage.local.remove('trafficSample'); // 清早期诊断残留
1100	  const cfg = await getConfig();
1101	  await chrome.alarms.clear('poll');
1102	  chrome.alarms.create('poll', { periodInMinutes: Math.max(1, cfg.intervalMinutes || 15) });
1103	  log.info('Alarm set: every ' + cfg.intervalMinutes + 'min, enabled=' + cfg.enabled);
1104	  await setupMustRemindAlarms();
1105	  // 前台变体监测闹钟
1106	  await chrome.alarms.clear('frontPoll');
1107	  const frontHours = Math.max(1, cfg.frontCheckIntervalHours || 3);
1108	  if (cfg.frontCheckEnabled !== false && cfg.productUrls && Object.keys(cfg.productUrls).length) {
1109	    chrome.alarms.create('frontPoll', { periodInMinutes: frontHours * 60 });
1110	    log.info('FrontPoll alarm set: every ' + frontHours + 'h');
1111	  } else {
1112	    log.info('FrontPoll alarm skipped (disabled or no URLs)');
1113	  }
1114	}
1115	chrome.runtime.onInstalled.addListener(() => { log.info('Extension installed/updated, setting up alarm'); setupAlarm(); });
1116	chrome.runtime.onStartup.addListener(() => { log.info('Chrome startup, setting up alarm'); setupAlarm(); });
1117	chrome.storage.onChanged.addListener((changes, area) => { if (area === 'local' && changes.config) { log.info('Config changed, reconfiguring alarm'); setupAlarm(); } });
1118	
1119	log.info('Service worker started');
1120	// SW 被唤醒时：清理历史假店 + 补闹钟
1121	cleanupFakeStores().catch((e) => log.warn('cleanupFakeStores: ' + (e && e.message || e)));
1122	setupAlarm();
