60	    const tag = el.tagName;
61	    if (tag === 'BUTTON' || tag === 'A' || tag === 'INPUT' || tag === 'SELECT') return true;
62	    if (el.getAttribute('role') === 'button' || el.getAttribute('role') === 'radio') return true;
63	    if (el.tabIndex >= 0) return true;
64	    // 检查是否有 pointer 事件监听（间接判断可交互）
65	    const style = window.getComputedStyle(el);
66	    if (style.cursor === 'pointer') return true;
67	    return false;
68	  }
